<?php
$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT b.*,u.name user_name FROM threshold_batches b LEFT JOIN users u ON u.id=b.user_id WHERE b.id=?');$q->execute([$id]);$b=$q->fetch();
if(!$b){echo '<div class="alert danger">Threshold batch not found.</div>';return;}
$q=$pdo->prepare('SELECT * FROM threshold_lines WHERE batch_id=? ORDER BY id');$q->execute([$id]);$rows=$q->fetchAll();$errors=json_decode($b['error_json']??'[]',true)?:[];
