<div class="page-head"><div><a class="back" href="?page=products">← Product Master</a><h1>Threshold Validation & Review</h1><p><?=e($b['batch_ref'])?> · <?=e($b['filename'])?></p></div><?=badge($b['status'],status_badge_class($b['status']))?></div>
<div class="batch-banner"><div><span>Rows</span><strong><?=count($rows)?></strong></div><div><span>Errors</span><strong><?=count($errors)?></strong></div><div><span>Uploaded By</span><strong><?=e($b['user_name'])?></strong></div><div><span>Confirmed At</span><strong><?=e($b['confirmed_at']?:'Pending')?></strong></div></div>
<?php if($errors):?><div class="alert danger">Validation failed. No thresholds were changed. Correct the source file and upload again.</div><div class="card"><div class="card-head"><h3>Validation Errors</h3><a class="btn secondary" href="download.php?type=threshold_errors&id=<?=$id?>">Download Error Report</a></div><ol><?php foreach($errors as $er):?><li><?=e($er)?></li><?php endforeach;?></ol></div><?php endif;?>
<div class="card table-wrap"><table class="table"><tr><th>Master SKU</th><th>Product</th><th>Previous Threshold</th><th>New Threshold</th><th>Change</th></tr><?php foreach($rows as $r):?><tr><td class="mono"><?=e($r['master_sku'])?></td><td><?=e($r['product_name'])?></td><td><?=(int)$r['old_threshold']?></td><td><b><?=(int)$r['new_threshold']?></b></td><td><?=((int)$r['old_threshold']===(int)$r['new_threshold'])?'Unchanged':'Update'?></td></tr><?php endforeach;?></table></div>
<?php if($b['status']==='To Review'&&can_action('confirm_thresholds')):?><div class="card final-confirm"><h3>3. Final Confirmation</h3><p>Apply all validated thresholds together. If a product changed after this preview, the entire update will be blocked.</p><form method="post" action="actions.php" data-confirm="Apply these <?=count($rows)?> product thresholds? Stock quantities will remain unchanged."><input type="hidden" name="action" value="confirm_thresholds"><input type="hidden" name="batch_id" value="<?=$id?>"><input type="hidden" name="return" value="threshold_review&id=<?=$id?>"><label class="ack"><input type="checkbox" name="review_ack" value="1" required> I reviewed all proposed threshold changes.</label><button class="btn primary">Confirm Threshold Update</button></form></div><?php endif;?>
